{
  "id": "0001-fraud-check",
  "title": "Fraud check before capture",
  "base": "__SYSEDIT_HEAD__",
  "request": "Add a fraud check before we capture payment.",
  "intent": "Score every order before we charge it. Risky orders go to manual review instead of being charged.",
  "flow": "checkout",
  "ops": [
    {
      "op": "addNode",
      "id": "fraud.score",
      "kind": "service",
      "label": "FraudService.score",
      "file": "src/fraud/service.ts",
      "takes": "order draft, customer",
      "returns": "risk score, 0 to 1",
      "note": "Threshold should be configurable.",
      "by": "engineer"
    },
    {
      "op": "addEdge",
      "from": "checkout.placeOrder",
      "to": "fraud.score",
      "by": "engineer"
    },
    {
      "op": "addNode",
      "id": "orderHold.create",
      "kind": "function",
      "label": "OrderHold.create",
      "file": "src/orders/hold.ts",
      "detail": "NEW · manual review queue",
      "by": "engineer"
    },
    {
      "op": "addBranch",
      "from": "fraud.score",
      "when": "≥ 0.8",
      "to": "orderHold.create",
      "by": "engineer"
    },
    {
      "op": "addBranch",
      "from": "fraud.score",
      "when": "< 0.8",
      "to": "payments.capture",
      "by": "engineer"
    },
    {
      "op": "removeEdge",
      "from": "checkout.placeOrder",
      "to": "payments.capture",
      "by": "engineer"
    },
    {
      "op": "annotate",
      "target": "fraud.score",
      "note": "On timeout, hold the order for review.",
      "by": "engineer"
    }
  ],
  "questions": [
    {
      "id": "q2",
      "severity": "blocking",
      "category": "failure-mode",
      "target": "FraudService.score",
      "headline": "FraudService adds a network call inside a 3 s budget",
      "question": "What happens when FraudService is slow or down? The gateway times out /checkout at 3 s, and the Stripe call already runs inside that budget.",
      "evidence": [
        {
          "file": "infra/gateway/routes.yaml",
          "line": 19,
          "endLine": 24
        },
        {
          "file": "src/checkout/service.ts",
          "line": 51,
          "endLine": 55
        }
      ],
      "checked": [
        "3 callers of placeOrder; only /checkout is user-facing",
        "No timeout wrapper around external calls in checkout",
        "src/lib/retry.ts already has withRetry() you could reuse"
      ],
      "options": [
        {
          "id": "open",
          "label": "Fail open: charge now, score in the background, flag for review",
          "effect": "Map updated: timeout branch → PaymentService.capture."
        },
        {
          "id": "closed",
          "label": "Fail closed: hold the order for review",
          "effect": "Map updated: timeout branch → OrderHold.create.",
          "ops": [
            {
              "op": "annotate",
              "target": "fraud.score",
              "note": "On timeout, hold the order for review."
            }
          ]
        },
        {
          "id": "retry",
          "label": "Retry once, then hold the order",
          "effect": "Map updated: score wrapped in withRetry(1), timeout → OrderHold.create."
        }
      ],
      "status": "answered",
      "answer": {
        "optionId": "closed",
        "at": "2026-10-01T09:00:00.000Z",
        "changedMap": true
      }
    },
    {
      "id": "q3",
      "severity": "blocking",
      "category": "consistency",
      "target": "InventoryService.reserve",
      "question": "Stock is reserved before the score runs. When an order is held for review, what happens to that reservation? Today it expires after 15 min unless the order is saved as paid.",
      "evidence": [
        {
          "file": "src/inventory/service.ts",
          "line": 7
        }
      ],
      "options": [
        {
          "id": "release",
          "label": "Release the stock as soon as the order is held",
          "ops": [
            {
              "op": "addEdge",
              "from": "orderHold.create",
              "to": "inventory.release"
            }
          ]
        },
        {
          "id": "extend",
          "label": "Keep it reserved until a reviewer decides"
        },
        {
          "id": "expire",
          "label": "Keep the 15 min expiry; cancel holds nobody reviews in time"
        }
      ],
      "status": "answered",
      "answer": {
        "text": "Keep it reserved until a reviewer decides, then release it if they reject the order.",
        "at": "2026-10-01T09:00:00.000Z",
        "changedMap": false
      }
    },
    {
      "id": "q4",
      "severity": "worth-checking",
      "category": "events",
      "target": "order.placed → EmailWorker (inferred)",
      "question": "Held orders aren't paid. Should they still emit order.placed and get a receipt email, or a new order.held?",
      "evidence": [
        {
          "file": "workers/email/index.ts",
          "line": 8
        }
      ],
      "status": "open"
    }
  ],
  "status": "approved",
  "risk": "high",
  "createdAt": "2026-10-01T09:00:00.000Z",
  "updatedAt": "2026-10-01T09:00:00.000Z",
  "history": [
